-- Tests numeriques initiaux (8 tests, 32 questions), repris de l'ancien projet. Seuil de reussite : 60.
-- Format JSON des questions (a respecter dans le backend) :
--   options_json          : [{"id":"A","texte":"..."}, ...]  (NULL pour TEXTE_LIBRE)
--   reponse_attendue_json : {"correct":["A"]}                (CHOIX_MULTIPLE : plusieurs ids)
--                           {"correctionManuelle":true}      (TEXTE_LIBRE : a corriger par un evaluateur)
-- Corrections par rapport a l'ancien seed : (1) les questions du test "Irrigation" etaient rattachees
-- par erreur au test "Transformation des cereales" ; (2) les propositions etaient dedoublonnees par
-- texte global (un "Vrai" deja insere faisait omettre les suivants).



SELECT DISTINCT t.competence_id, m.id, TRUE
FROM test_numerique t
JOIN methode_validation m ON m.code = 'TEST_NUMERIQUE';
